"""Genera y ejecuta el notebook v2 sin modificar la primera prueba."""
from pathlib import Path
import sys,json,tempfile
import nbformat as nbf
from nbclient import NotebookClient
from jupyter_client import KernelManager
from jupyter_client.kernelspec import KernelSpecManager

ROOT=Path(__file__).resolve().parents[1]

def main():
    md=nbf.v4.new_markdown_cell
    code=nbf.v4.new_code_cell
    cells=[
      md('# Versión 2: incorporar historia y recuperar Temuco y Padre Las Casas\n\nClasificación supervisada de crecimiento de al menos 1% anual. Proyecto individual tutorado con Pablo Valenzuela. **2024 ya se observó en v1**: esta versión produce una reevaluación temporal exploratoria, no una prueba final nueva e independiente. La primera prueba se conserva sin reemplazar sus datos ni resultados.'),
      md('## 1. Hipótesis y protocolo\n\nPoblación y edades de un único censo no capturaron suficientemente la dinámica demográfica. Se añade crecimiento anterior y se comparan alternativas con cambios en las proporciones de edad. Se conserva el umbral de 1%. La ampliación nace del diagnóstico de v1, que ya incluyó 2024. La elección mecánica de esta nueva configuración no usa etiquetas de 2024; después de la reevaluación v2 no se cambian parámetros para subir ese resultado.\n\nEntradas de entrenamiento: censos 1992 y 2002; respuesta: crecimiento 2002–2017. Selección: cinco particiones de las 314 comunas de esa etapa. Cada ejemplo se predice sin estar en el ajuste de su partición. Se elige por media de F1 macro, exactitud balanceada y simplicidad. Diez candidatos se registraron antes de entrenar v2. Esta CV es entre comunas de una época; no demuestra generalización a futuros períodos.'),
      code("from pathlib import Path\nimport sys,json\nimport numpy as np\nimport pandas as pd\nimport joblib\nfrom sklearn.model_selection import StratifiedKFold\nfrom sklearn.tree import export_text\nfrom IPython.display import display,Image\nROOT=Path.cwd()\nif not (ROOT/'experiments').exists():ROOT=ROOT.parent\nsys.path.insert(0,str(ROOT/'experiments'))\nimport crecimiento_v2 as v2\nimport crecimiento_censal as v1\nOUT=v2.OUT\nprotocol=json.loads(v2.PROTOCOL.read_text())\nsummary=json.loads((OUT/'resumen.json').read_text())\nquality=json.loads((OUT/'calidad_datos.json').read_text())\nclosed=json.loads((OUT/'seleccion_cerrada.json').read_text())\nprofiles=pd.read_csv(OUT/'perfiles_censales.csv')\ncore=summary['core_codes']\nprint('Selección usa etiquetas de 2024:',closed['selection_used_2024_labels'])\nprint('2024 conocido en v1:',closed['2024_seen_in_v1'])\nprint('Clasificador seleccionado:',closed['selected'])"),
      md('## 2. Recuperación geográfica y procedencia\n\nLa exclusión inicial fue conservadora. REDATAM ya publica Temuco y Padre Las Casas por separado en 1992. La Ley 19.391 creó Padre Las Casas en 1995; que exista una tabla retrospectiva no significa que existiera jurídicamente en 1992.\n\nEl INE comunicó el 12-09-2018 que actualizó las bases y REDATAM de 2002 a la nueva división administrativa. La Ley 20.578 trasladó un sector desde Freire a Padre Las Casas en 2012. Se utiliza la publicación actual de 2002, no se suman personas de San Ramón manualmente. **1992 se excluye de la historia usada para Padre Las Casas** porque no se acredita su ajuste al traspaso posterior. Su clasificación histórica usa 2002 y 2017; el escenario futuro usa 2017 y 2024.\n\nLa recuperación es preliminar y falta una auditoría cartográfica exhaustiva. Las dos comunas quedan fuera del ajuste y selección históricos, y se presentan como aplicaciones adicionales. La comparación v1/v2 mantiene las 314 originales.'),
      code("sources=json.loads((ROOT/'data/raw/ine/crecimiento/fuentes.json').read_text())\nterritorial=json.loads((ROOT/'data/raw/ine/crecimiento/fuentes_territoriales_v2.json').read_text())\ndisplay(pd.DataFrame(sources['files'])[['file','bytes','sha256']])\ndisplay(pd.DataFrame(territorial['files'])[['file','url','bytes','sha256']])\ndisplay(pd.DataFrame(quality['recovered']))\ndisplay(profiles.loc[profiles.code.isin([9101,9112]),['name','year','population','young','old']])\nprint('Contraste independiente 2017:',quality['independent_2017_check'])\nassert set(profiles.year)=={1992,2002,2017,2024}\nassert profiles.loc[(profiles.code==9112)&(profiles.year==1992)].empty"),
      md('## 3. Datos, variables y preparación\n\nUnidad: comuna-período; habitantes no son muestras independientes. La población es un recuento de razón; las proporciones y tasas son numéricas. Identificadores y nombres son nominales y quedan fuera de las entradas. Se trabaja con residentes habituales con comuna identificada. En 2017 no equivale al total de personas censadas físicamente en una comuna: Padre Las Casas tiene 74.911 residentes identificados en la tabla utilizada, frente a 76.126 censados allí. Cobertura y no respuesta afectan la comparación.\n\nSe calculan seis posibles entradas. Los cambios de proporción se dividen por la duración anterior. El Random Forest elegido usa cuatro: logaritmo de población, menores de 15, 65 o más y crecimiento anterior. El escalado de las alternativas de Logistic Regression ocurre dentro de cada partición mediante Pipeline. No se mezcla la población final con las entradas, ni se utilizan cifras de 2012 o proyecciones como observaciones.'),
      code("display(profiles.groupby('year').agg(comunas=('code','nunique'),residentes=('population','sum')))\ninitial,X,y_previous=v2.inputs(profiles,1992,2002,core)\ny,_,_=v2.labels(profiles,2002,2017,core)\ndisplay(X.describe().T)\nprint('Clases de respuesta:',np.bincount(y),'filas:',len(X))\ndisplay(X.head())\nprint('Entradas seleccionadas:',closed['candidate']['features'])"),
      md('## 4. Entrenamiento y validación reproducidos\n\nSe muestran todos los candidatos, incluidos aquellos que no mejoraron. La media por partición determina la selección. El F1 conjunto de predicciones fuera del ajuste es una métrica descriptiva distinta; no se reemplaza el criterio de selección por ella. Se reproduce aquí la CV del candidato elegido, utilizando únicamente respuestas hasta 2017. La elección está guardada antes de reevaluar 2024.'),
      code("display(pd.read_csv(OUT/'comparacion_validacion.csv').sort_values('selection_f1_mean',ascending=False))\nfolds=StratifiedKFold(n_splits=5,shuffle=True,random_state=2025)\npredictions=np.zeros(len(y),dtype=int)\nfold_f1=[]\nfor train,valid in folds.split(X,y):\n    classifier=v2.make_model(closed['candidate']).fit(X.iloc[train],y[train])\n    predictions[valid]=classifier.predict(X.iloc[valid])\n    fold_f1.append(v1.metrics(y[valid],predictions[valid])['f1_macro'])\nassert np.isclose(np.mean(fold_f1),summary['validation'][closed['selected']]['selection_f1_mean'])\nprint('F1 medio reproducido:',np.mean(fold_f1),'F1 conjunto:',v1.metrics(y,predictions)['f1_macro'])\nhistorical=v2.make_model(closed['candidate']).fit(X,y)\ninitial_test,X_test,old=v2.inputs(profiles,2002,2017,sorted(core+[9101,9112]))\nsaved=joblib.load(OUT/'clasificador_historico.joblib')\nnp.testing.assert_allclose(historical.predict_proba(X_test),saved.predict_proba(X_test))\nprint('Ajuste histórico reproducido con 314 respuestas hasta 2017')"),
      md('## 5. Reevaluación temporal exploratoria\n\nEl Random Forest elegido obtiene 205 aciertos de 314 y F1 macro 0,642. V1 obtuvo 169 y 0,528. La continuidad anterior mantiene 213 y 0,663. **Se mejoró frente a v1, pero no se supera la referencia práctica.** El Random Forest detecta 130 de las 150 comunas con crecimiento alto, frente a 73 de continuidad; produce 89 falsas alertas frente a 24. Esa diferencia puede interesar para revisar casos, sin acreditar superioridad general o utilidad futura. Las dos comunas recuperadas no se añaden al denominador para presentar una mejora artificial.\n\nEl remuestreo pareado de regiones produce un intervalo exploratorio de diferencia de F1 que contiene cero. No acredita una ventaja clara. La variación temporal, las duraciones y la geografía limitan la inferencia; 2024 sigue siendo una reevaluación de datos ya conocidos.'),
      code("display(pd.DataFrame([{'alternativa':k,**{metric:r[metric] for metric in ('n','f1_macro','balanced_accuracy','accuracy')}} for k,r in summary['test'].items()]))\ndisplay(pd.DataFrame(summary['test']['modelo']['confusion'],index=['Real <1%','Real ≥1%'],columns=['Predice <1%','Predice ≥1%']))\ndisplay(pd.DataFrame(summary['test']['modelo']['classes']).T)\nprint('Comparación pareada:',summary['paired_vs_persistence'])\ndisplay(Image(filename=str(OUT/'evaluacion.png')))\nindividual=pd.read_csv(OUT/'predicciones_historicas.csv')\ndisplay(individual.loc[individual.code.isin([9101,9112]),['name','population','previous_population','previous_rate','actual_population','actual_rate','predicted_class','actual_class','correct']])"),
      md('## 6. Modelo futuro separado y utilidad de la aplicación\n\nEl escenario 2024–2031 utiliza el mismo diseño elegido, pero un ajuste distinto con 630 ejemplos: 314 de 2002–2017 y 316 de 2017–2024. Puede usar respuestas de 2024 porque ese resultado ya se conoce al emitir el escenario. El modelo histórico se conserva por separado, sin esas respuestas en su entrenamiento. No existe aún un resultado de 2031; su precisión futura no está demostrada.\n\nLa aplicación entrega clasificación y continuidad anterior juntas. Si difieren, muestra la discrepancia; si coinciden, no la presenta como garantía. Permite revelar el resultado histórico, consultar ambas comunas y examinar procedencia. El puntaje interno no es una probabilidad calibrada.'),
      code("y_later,_,_=v2.labels(profiles,2017,2024,sorted(core+[9101,9112]))\nfuture=v2.make_model(closed['candidate']).fit(pd.concat([X,X_test]),np.concatenate([y,y_later]))\nlatest,future_X,_=v2.inputs(profiles,2017,2024,sorted(core+[9101,9112]))\nsaved_future=joblib.load(OUT/'clasificador_futuro.joblib')\nnp.testing.assert_allclose(future.predict_proba(future_X),saved_future.predict_proba(future_X))\nprint('Ajuste futuro reproducido:',len(X)+len(X_test),'ejemplos; no hay respuesta observada de 2031')\nprint('Importancias del modelo futuro:',summary['explanation'])\nprint('Un árbol de los 300 del modelo histórico, como ejemplo didáctico:')\nprint(export_text(saved.named_steps['classifier'].estimators_[0],feature_names=closed['candidate']['features'],max_depth=2))"),
      md('## Fuentes y límites académicos\n\n- [INE: censos y REDATAM](https://www.ine.gob.cl/estadisticas-por-tema/demografia-y-poblacion/censo-de-poblacion-y-vivienda).\n- [INE: actualización de DPA de 2002 y 2017, 12-09-2018](https://www.ine.gob.cl/sala-de-prensa/prensa/general/noticia/2019/09/16/ine-actualiza-informaci%C3%B3n-de-censo-2017-a-la-nueva-divisi%C3%B3n-pol%C3%ADtica-administrativa-incorporando-la-nueva-regi%C3%B3n-de-%C3%B1uble).\n- [Ley 19.391](https://www.bcn.cl/leychile/Navegar?idNorma=30758) y [Ley 20.578](https://www.bcn.cl/leychile/navegar?idNorma=1038291).\n- [MMA: documento territorial de 2015](https://airechile.mma.gob.cl/download/DO-PDA-Temuco-y-Padre-Las-%20Casas.pdf), usado como antecedente de límites, sin cifras de 2012 para el modelo.\n\nAtribución INE: tabulados y derivados censales bajo CC BY-SA 4.0, transformaciones documentadas. La recuperación cartográfica es preliminar. La revisión académica y calendario individual con Pablo Valenzuela quedan por acordar. No se ha enviado una comunicación al profesor.')
    ]
    notebook=nbf.v4.new_notebook(cells=cells)
    notebook.metadata.kernelspec={'display_name':'Python 3','name':'python3','language':'python'}
    notebook.metadata.language_info={'name':'python','version':sys.version.split()[0]}
    with tempfile.TemporaryDirectory() as directory:
        spec=Path(directory)/'censo-v2'
        spec.mkdir()
        (spec/'kernel.json').write_text(json.dumps({'argv':[sys.executable,'-m','ipykernel_launcher','-f','{connection_file}'],'display_name':'Censos v2','language':'python'}))
        manager=KernelSpecManager(kernel_dirs=[directory])
        client=NotebookClient(notebook,timeout=120,resources={'metadata':{'path':str(ROOT)}},kernel_name='censo-v2')
        client.km=KernelManager(kernel_name='censo-v2',kernel_spec_manager=manager)
        client.execute()
    nbf.validate(notebook)
    target=ROOT/'experiments/estudio_crecimiento_v2.ipynb'
    nbf.write(notebook,target)
    print('Notebook v2 ejecutado:',target)

if __name__=='__main__':main()
